head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//#include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDINS15900.xml";
scwin.cnt = 0;
scwin.prevRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 지표 표준코드 관리를 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    dts_List.removeAll();

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) == false) {
        return false;
    }
    fn_CtrlBtn_temp("update");
    if (document.getElementById("btn_createstdcd")) {
        btn_createstdcd.setDisabled(true); // 표준코드등록
        btn_createstdcd.src = "../img/ins/btn_createstdcd_d.gif";
    }
    txb_STD_CD.setReadOnly(true);
    txb_STD_CD.setStyle("backgroundcolor", "#b9d4f7");

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS15900_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdIndcInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.getValue() + "&{P}ISU_NM=" + txb_pISU_NM.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}STD_CD_GRNT_DD_SDATE=" + edt_pSTD_CD_GRNT_DD_SDATE.getValue() + "&{P}STD_CD_GRNT_DD_EDATE=" + edt_pSTD_CD_GRNT_DD_EDATE.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : fn_new
 * 설명       :  조회버튼 클릭시 신규등록을 위한 dataset 세팅 
 ***********************************************/
scwin.fn_new = function() {
    dts_List.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ULDINS15900_LIST_OUT";
    dts_List.reset();
    dts_List.insertRow();
    fn_CtrlBtn_temp("insert");
    if (document.getElementById("btn_createstdcd")) {
        btn_createstdcd.setDisabled(false); // 표준코드등록
        btn_createstdcd.src = "../img/ins/btn_createstdcd.gif";
    }
    img_ISUR_CD.setDisabled(false);
    img_ISUR_CD.src = "../img/btn_search.gif";

    //txb_STD_CD.readOnly = false;
    //txb_STD_CD.style.background='white';

    $c.stf.setObjectValue(cmb_ACTIV_TP_CD, "Y");
};


/********************************************** 
 * 함수명   : fn_formCheck
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheck = function() {
    if (txb_ISUR_CD.getValue() == "" || txb_ISUR_CD.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISUR_CD).length != 5) {
        $c.win.alert("올바른 지표발행기관코드 넣어주세요");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ACTIV_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "활성여부"));
        cmb_ACTIV_TP_CD.focus();
        return false;
    }
    if (txb_ISU_NM.getValue() == "" || txb_ISU_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
        txb_ISU_NM.focus();
        return false;
    }
    if (txb_ISU_ABBRV.getValue() == "" || txb_ISU_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() == "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
        txb_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CFI_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI코드"));
        txb_CFI_CD.focus();
        return false;
    }
};




/********************************************** 
 * 함수명   : ins_register
 * 설명       : 지표 표준코드 관리 등록전 표준코드 체크 한다
 ***********************************************/
scwin.ins_register = function() {
    if (scwin.fn_formCheck() == false) {
        return;
    }
    dts_List.setCellData(dts_List.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_stdcd.Action = "/StdCdIndcInfoAction.do?method=registerStdCdIndcInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&STDCDFLAG=Y";
    trs_stdcd.KeyName = "toinb_dataid4";
    trs_stdcd.KeyValue = "JSP(O:pReturnOut=dts_stdcd,I:pInput=dts_List)";
    trs_stdcd.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_stdcd.Post();
};


/********************************************** 
 * 함수명   : ins_register_insert	
 * 설명       : 지표 표준코드 관리 등록 한다. screenProcsTpCd 03
 ***********************************************/
scwin.ins_register_insert = function() {
    dts_List.setCellData(dts_List.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    if (scwin.fn_formCheck() == false) {
        return;
    }
    trs_save.Action = "/StdCdIndcInfoAction.do?method=registerStdCdIndcInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&STDCDFLAG=N";
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInput=dts_List)";
    trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_save.Post();
};



/********************************************** 
 * 함수명   : ins_modify	
 * 설명       : 지표 표준코드 관리를 수정 한다. screenProcsTpCd 03
 ***********************************************/
scwin.ins_modify = function(mflag) {
    var screenProcsTpCd = "03";
    if (screenProcsTpCd == '03') {
        // 수정

        if (!$c.cp.isModified(dts_List)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISUR_CD).length != 5) {
            $c.win.alert("올바른 지표발행기관코드 넣어주세요");
            txb_ISUR_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_ACTIV_TP_CD) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "활성여부"));
            cmb_ACTIV_TP_CD.focus();
            return false;
        }
        if (txb_ISU_NM.getValue() == "" || txb_ISU_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_NM.focus();
            return false;
        }
        if (txb_ISU_ABBRV.getValue() == "" || txb_ISU_ABBRV.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() == "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
            txb_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (mflag == "N") return;
        trs_save.Action = "/StdCdIndcInfoAction.do?method=modifyStdCdIndcInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};


/********************************************** 
 * 함수명   : fn_Change_cfi
 * 설명       : cfi 변경 설정 - 채권과 동일 .....
 ***********************************************/
scwin.fn_Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    cfi = "T";
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_group);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_1);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_2);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_3);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_4);
    txb_CFI_CD.setValue(cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_set_cfi_fisn
 * 설명       : cfi 변경시 fisn 셋팅
 ***********************************************/
scwin.fn_set_cfi_fisn = function() {
    var ISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    ISUR_CD = ISUR_CD.substring(0, 2);
    var fisn1 = "";
    var fisn2 = "";
    if (ISUR_CD == "01") {
        fisn1 = "BOK";
        fisn2 = "KRW";
    } else if (ISUR_CD == "02") {
        fisn1 = "KRX";
        fisn2 = "Idx KR";
    } else if (ISUR_CD == "03") {
        //사용안함

    } else if (ISUR_CD == "04") {
        //사용안함

    }

    //fisn입력
    $c.stf.setObjectValue(txb_fisn1, fisn1);
    $c.stf.setObjectValue(txb_fisn2, fisn2);
};


/********************************************** 
 * 함수명   : fn_set_Change
 * 설명       :  상세 조회시 CFI 상세 설정 
 ***********************************************/
scwin.fn_set_Change = function(str_cfi) {
    if (str_cfi == "") return;
    $c.stf.setObjectValue(cmb_cb_p_group, str_cfi.substring(1, 2));
    $c.stf.setObjectValue(cmb_cb_p_attr_1, str_cfi.substring(2, 3));
    $c.stf.setObjectValue(cmb_cb_p_attr_2, str_cfi.substring(3, 4));
    $c.stf.setObjectValue(cmb_cb_p_attr_3, str_cfi.substring(4, 5));
    $c.stf.setObjectValue(cmb_cb_p_attr_4, str_cfi.substring(5, 6));
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);

    //cfi콤보셋팅
    ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "18", "T", "", "", "G");
    //hidden패널
    //showObj(panel_12,false);

    txb_pSTD_CD.setValue("KRD");
    img_ISUR_CD.setDisabled(true);
    img_ISUR_CD.src = "../img/btn_search_d.gif";
    txb_pSTD_CD.focus();
};
scwin.btn_prcnm_onclick = function() {
    txb_param1.setValue(txb_STD_CD.getValue()); // 표준코드
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS93300", "표준코드 처리자 조회", "620", "420");
};
scwin.txb_pSTD_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pSTD_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.txb_pISU_NM_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISU_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.btn_createstdcd_onclick = function() {
    scwin.ins_register();
};
scwin.btn_new_onclick = function() {
    scwin.fn_new();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
        var CFI_CD = dts_List.getCellData(dts_List.getRowPosition(), "CFI_CD");
        if (CFI_CD != undefined) {
            scwin.fn_set_Change(CFI_CD);
        }
    }
    scwin.cnt = rowcount;
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    scwin.cnt = 0;
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.img_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_ISUR_NM, "ULDINS91400", "발행기관 코드", "570", "430");
    //cfi fisn 초기화
    $c.stf.setObjectValue(txb_CFI_CD, "");
    $c.stf.setObjectValue(txb_fisn1, "");
    $c.stf.setObjectValue(txb_fisn2, "");
    scwin.fn_set_Change("");
};
scwin.img_pISUR_CD_onclick = function() {
    ins_popupOpen(txb_pISUR_CD, "", "ULDINS91400", "발행기관 코드", "570", "430");
};
scwin.btn_modify_onclick = function() {
    if (scwin.ins_modify("N") == false) return;
    ins_popupOpen("", "", "ULDINS93900", "수정사유", "470", "190");
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "지표 표준코드 관리 "));
    scwin.ins_search();
};
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (dts_List.getRowStatus(row) == 1) return;
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    img_ISUR_CD.setDisabled(true);
    img_ISUR_CD.src = "../img/btn_search_d.gif";
    var CFI_CD = dts_List.getCellData(dts_List.getRowPosition(), "CFI_CD");
    if (CFI_CD != undefined) {
        scwin.fn_set_Change(CFI_CD);
    }
};
scwin.img_pSTD_CD_GRNT_DD_SDATE_onclick = function() {
    popUpCalendar2(edt_pSTD_CD_GRNT_DD_SDATE);
};
scwin.img_pSTD_CD_GRNT_DD_EDATE_onclick = function() {
    popUpCalendar2(edt_pSTD_CD_GRNT_DD_EDATE);
};
scwin.dts_Rst_OnLoadCompleted = function(rowcount) {
    // 발행기관 등록후 결과값을 받아 처리한다.
    var RESULT_CONTN = dts_Rst.getCellData(0, "RESULT_CONTN");
    if (RESULT_CONTN != "SUCCESS") {
        $c.win.alert(RESULT_CONTN);
    }
};
scwin.dts_stdcd_OnLoadCompleted = function(rowcount) {
    // 발행기관 등록후 결과값을 받아 처리한다.
    var RESULT_CONTN = dts_stdcd.getCellData(0, "RESULT_CONTN");
    var r = confirm("표준코드 : " + RESULT_CONTN + " 등록하시겠습니까?");
    if (r == 1) {
        $c.stf.setObjectValue(txb_STD_CD, RESULT_CONTN);
        scwin.ins_register_insert();
    } else {
        $c.stf.setObjectValue(txb_STD_CD, "");
    }
};
scwin.trs_stdcd_OnFail = function() {
    alert_tr_error(trs_stdcd);
};
scwin.txb_pISUR_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.txb_STD_CD_onkeyup = function() {
    fn_DelChar(this);
};
scwin.txb_ISUR_CD_onkeyup = function() {

};
scwin.txb_ISU_NM_onkeyup = function() {
    /*
1) 통화 : TCNXXX 01
2) 상품 : MRTXXX 04
3) 금리 : MRRXXX 03
4) 지수 : TIEXXX 02
*/
    if ($c.stf.getObjectValue(txb_CFI_CD) == "") {
        var ISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
        ISUR_CD = ISUR_CD.substring(0, 2);
        //	alert(ISUR_CD);
        var cfi = "";
        var fisn1 = "";
        var fisn2 = "";
        if (ISUR_CD == "01") {
            cfi = "TCNXXX";
            fisn1 = "BOK";
            fisn2 = "KRW";
        } else if (ISUR_CD == "02") {
            cfi = "TIEXXX";
            fisn1 = "KRX";
            fisn2 = "Idx KR";
        } else if (ISUR_CD == "03") {
            //사용안함
            cfi = "MRRXXX";
        } else if (ISUR_CD == "04") {
            //사용안함
            cfi = "MRTXXX";
        }
        $c.stf.setObjectValue(txb_CFI_CD, cfi);
        scwin.fn_set_Change(cfi);

        //fisn입력
        $c.stf.setObjectValue(txb_fisn1, fisn1);
        $c.stf.setObjectValue(txb_fisn2, fisn2);
    }
};
